uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float radius : 0.05 .. 0.3 = 0.1;
uniform float height : 0.1 .. 0.5 = 0.3;
uniform float blobs : 0.0 .. 5.0 = 2.0;
uniform float spread : 0.0 .. 1.0 = 0.5;
uniform vec3 tint : color = 1.0, 0.2, 0.0;
uniform float intensity : 0.0 .. 2.0 = 1.0;
uniform bool invert = false;

state fixed ph;
state fixed drift;

void update() {
  ph = fract(ph + fixed(dt * speed * 0.5));
  drift = drift + fixed(dt * speed * 0.3);
}

vec3 shade(Led led) {
  fixed s = fixed(led.s);
  fixed x = fixed(led.pos.x);
  fixed z = fixed(led.pos.z);
  fixed y = fixed(led.pos.y);

  // radial distance from central axis (0..1)
  fixed r = sqrt(fixed(x*x + fixed(z*z)));
  // normalize into a pseudo 2D plane
  fixed nx = x / max(r, fixed(0.01));
  fixed nz = z / max(r, fixed(0.01));

  // generate blob pattern using fixed-point noise-like LUTs
  fixed hash1 = hash(float(led.idx));
  fixed hash2 = hash(float(led.idx) * fixed(3.2));
  fixed n = mix(hash1, hash2, fixed(0.5));

  // blobs: offset from blob count, then a smooth bump
  fixed b = fract(s * fixed(blobs) + ph);
  fixed bump = smoothstep(fixed(0.0), fixed(0.5), fixed(1.0) - abs(fixed(2.0) * b - fixed(1.0)));
  bump = bump * fixed(spread);

  // combine geometry with blob field
  fixed geom = exp(fixed(-r * fixed(3.0))) * fixed(1.0 + fixed(0.2) * sin(fixed(led.uv.y) * fixed(6.2832) + ph));

  // final intensity per LED
  fixed val = bump * geom;

  // hsv to rgb, all fixed args use the integer path
  fixed h = fract(r * fixed(3.0) + drift);
  fixed s_ = fixed(0.9);
  fixed v = clamp(val * fixed(intensity), fixed(0.0), fixed(1.0));
  vec3 col = hsv2rgb(h, s_, v);
  return col * tint;
}

